param([ValidateSet('x86','x64')][string]$Platform)
$ErrorActionPreference='Stop'
$repoRoot=Split-Path $PSScriptRoot -Parent
$source=Join-Path $repoRoot '.deps/dxvk-remix'
if(!$Platform){
 python "$repoRoot/scripts/generate_ipc_api_failure_test.py"
 if($LASTEXITCODE -ne 0){throw 'API extraction failed'}
 foreach($arch in @('x86','x64')){& powershell.exe -NoProfile -File $PSCommandPath -Platform $arch;if($LASTEXITCODE -ne 0){throw "API test failed $arch"}}
}else{
 . (Join-Path $source 'bridge/build_common.ps1')
 SetupVS -Platform $Platform -VcVarsVer '14.29'
 Push-Location (Join-Path $repoRoot '.deps/ipc-api')
 try{
  & cl.exe /nologo /std:c++17 /EHsc /O2 /W3 /DNOMINMAX "/I$source/bridge/src/util" "/I$source/bridge/src/client" "/I$repoRoot/tests" ipc_api.cpp "/Fe:api-$Platform.exe"
  if($LASTEXITCODE -ne 0){throw 'API compilation failed'}
  & ".\api-$Platform.exe"
  if($LASTEXITCODE -ne 0){throw 'API assertions failed'}
 }finally{Pop-Location}
}
